import React, {Component} from 'react';
import {Dimensions, Image, Text, TouchableNativeFeedback, View,} from 'react-native';
import {bindActionCreators} from 'redux';
import {connect} from 'react-redux';
import NavigationBar from '../Basic/NavigationBar';
import styles from './PlaygroundStyles';
import {goTo} from "../../Redux/Navigation/NavigationActions";
import {Link} from 'react-router-native';
import axios from "axios/index";
import firebaseApp from '../Firebase.js';

firebaseApp.analytics().setCurrentScreen("PGhome");

const screen = Dimensions.get('window');

class PgHome extends Component<{}> {
  constructor() {
    super();
    this.state = {
      buttons: [
        'CONCEPT GYM',
        'PRACTICE TEST',
        'CHALLENGE',
      ],
      links: [
        '/concept',
        '/test',
        '/challenge',
      ],
      backgrounds: [
        'data:image/png;base64,',
        'data:image/png;base64,',
        'data:image/png;base64,',
      ]
    }
  }

  componentDidMount() {
    const {id} = this.props.user;
    axios.get(`http://api.classcast.in/classcast/ranking/rankings/${id}/`)
      .then(res => this.setState(
        {
          score: res.data.Score,
          rank: res.data.Rank,
        }
      ));
    axios.get(`http://api.classcast.in/classcast/streak/streak/${id}/`)
      .then(res => this.setState(
        {
          streak: res.data,
        }
      ))
  }

  render() {
    return (
      <View style={styles.container}>
        <Image
          style={{
            position: 'absolute',
            top: 0,
            height: screen.height,
            width: screen.width,
          }}
          source={{uri: 'data:image/png;base64,'}}
        />
        <NavigationBar
          noDashboard={true}
          leftButtonStyle={'MENU_WHITE'}
          rightButtonStyle={'NONE'}
          
        />
        <Text style={styles.sectionHeader}>PLAYGROUND</Text>
        <View style={styles.playStats}>
          <View style={[styles.playStatContainer, {borderRightWidth: 1, borderRightColor: 'rgba(255,255,255,0.4)'}]}>
            <View style={{flexDirection: 'row', alignItems: 'flex-end'}}>
              <Text style={styles.playStatValue}>{this.state.streak}</Text>
              <Text style={styles.playStatSuffix}>{this.state.streak > 1 ? 'DAYS' : 'DAY'}</Text>
            </View>
            <Text style={styles.playStatLabel}>STREAK</Text>
          </View>
          <View style={styles.playStatContainer}>
            <View>
              <Text style={styles.playStatValue}>{this.state.score || 0}</Text>
            </View>
            <Text style={styles.playStatLabel}>SCORE</Text>
          </View>
          <View style={[styles.playStatContainer, {borderLeftWidth: 1, borderLeftColor: 'rgba(255,255,255,0.4)'}]}>
            <View>
              <Text style={styles.playStatValue}>{this.state.rank || 0}</Text>
            </View>
            <Text style={styles.playStatLabel}>RANK</Text>
          </View>
        </View>
        {
          this.state.buttons.map((button, index) => (
            <Link component={TouchableNativeFeedback} key={'PgHomeButtons' + index} to={this.state.links[index]}>
              <View style={[styles.largeButton]}>
                <Image
                  style={{
                    width: '100%',
                    height: '100%',
                    zIndex: 0,
                  }}
                  resizeMode={'cover'}
                  source={{uri: this.state.backgrounds[index]}}
                />
                <Text style={[styles.buttonText, styles.largeButtonText, {fontFamily: 'Montserrat-SemiBold'}]}>
                  {button}
                </Text>
              </View>
            </Link>
          ))
        }
      </View>
    )
  }
}

const mapStateToProps = state => ({
  user: state.user
});
const mapDispatchToProps = dispatch => bindActionCreators({
  goTo: goTo,
}, dispatch);

export default connect(mapStateToProps, mapDispatchToProps)(PgHome)